#!/usr/bin/env python3
"""runtime-patching-tools.py <folder>: ONE CASE A FOLDER: WHAT TOOLS AND TESTS PATCH AT RUN TIME (graceful-fs, nock, sinon, mockdate, APM agents, loggers, polyfills): a member of a host module, a global function, a global constructor, a member of console | process | performance | crypto | Bun, a global of the program's own. main.ts patches, user.ts (another module, typed, compiled) uses: by a named import, by a namespace, by a default import, by require, by the bare global, by globalThis.x; before and behind the patch, and behind its removal. Either the patch is seen as in plain Bun or the patching is refused in words (the built-ins of the language are locked)."""
import os, sys
out = sys.argv[1]; cases = {}
D = 'declare const console: any, process: any, Bun: any, require: any, performance: any, crypto: any, globalThis: any;\n'
def case(name, user, main, more=None):
    cases[name] = {"user.ts": D + user + "\n", "main.ts": D + 'import * as user from "./user";\nconst attempt = (f: () => unknown): unknown => { try { return f(); } catch (e) { return "THROWS " + (e as Error).name + ": " + String((e as Error).message).split("\\n")[0].slice(0, 80); } };\nconst real = console.log.bind(console);\n' + main + "\n", **(more or {})}
case("a-member-of-node-fs", 'import { existsSync } from "node:fs"; import * as ns from "node:fs"; import def from "node:fs"; const req = require("node:fs"); const { existsSync: taken } = require("node:fs");\nexport const all = (): string => [existsSync("/nowhere"), ns.existsSync("/nowhere"), def.existsSync("/nowhere"), req.existsSync("/nowhere"), taken("/nowhere")].join();',
     'const fs = require("node:fs"); const old = fs.existsSync; real(user.all()); real(attempt(() => { fs.existsSync = () => "patched"; return "patched it"; })); real(user.all()); fs.existsSync = old; real(user.all());')
case("a-member-of-node-fs-patched-and-synced", 'import { existsSync } from "node:fs"; import * as ns from "node:fs";\nexport const all = (): string => [existsSync("/nowhere"), ns.existsSync("/nowhere")].join();',
     'const fs = require("node:fs"); const { syncBuiltinESMExports } = require("node:module"); real(attempt(() => { fs.existsSync = () => "patched"; syncBuiltinESMExports(); return "synced"; })); real(user.all());')
case("a-member-of-node-http", 'import http from "node:http"; import { request } from "node:http";\nexport const all = (): string => [typeof http.request, (http.request as any).mark ?? "no mark", (request as any).mark ?? "no mark"].join();',
     'const http = require("node:http"); const old = http.request; real(attempt(() => { http.request = Object.assign(function (...a: unknown[]) { return old.apply(http, a); }, { mark: "wrapped" }); return "wrapped it"; })); real(user.all());')
case("a-prototype-of-a-host-module", 'import { EventEmitter } from "node:events";\nexport const all = (): string => { const e = new EventEmitter(); const seen: string[] = []; e.on("x", () => seen.push("listener")); e.emit("x"); return seen.join(); };',
     'const { EventEmitter } = require("node:events"); const old = EventEmitter.prototype.emit; const log: string[] = []; real(attempt(() => { EventEmitter.prototype.emit = function (name: string, ...a: unknown[]) { log.push("emit " + name); return old.call(this, name, ...a); }; return "patched it"; })); real(user.all(), log.join());')
case("console-log", 'export const all = (): void => { console.log("through console.log", 1); globalThis.console.log("through globalThis"); const { log } = console; log("taken out late"); };\nexport const early = console.log;',
     'const seen: string[] = []; const old = console.log; real(attempt(() => { console.log = (...a: unknown[]) => { seen.push(a.join(" ")); }; return "patched it"; })); user.all(); user.early("taken out early"); console.log = old; real(JSON.stringify(seen)); user.all();')
case("console-error-and-warn", 'export const all = (): void => { console.error("an error"); console.warn("a warning"); console.info("an info"); console.debug("a debug"); };',
     'const seen: string[] = []; for (const k of ["error", "warn", "info", "debug"]) console[k] = (...a: unknown[]) => { seen.push(k + ":" + a.join(" ")); }; user.all(); real(JSON.stringify(seen));')
case("the-console-itself", 'export const all = (): void => { console.log("to whichever console there is"); };',
     'const seen: string[] = []; real(attempt(() => { globalThis.console = { log: (...a: unknown[]) => { seen.push(a.join(" ")); } }; return "replaced it"; })); user.all(); real(JSON.stringify(seen));')
case("stdout-write", 'export const all = (): void => { process.stdout.write("written\\n"); console.log("logged"); };',
     'const seen: string[] = []; const old = process.stdout.write; process.stdout.write = (s: string) => { seen.push(s); return true; }; user.all(); process.stdout.write = old; real(JSON.stringify(seen));')
case("global-fetch", 'export const all = async (): Promise<string> => [await (fetch as any)("http://localhost:1/x"), await globalThis.fetch("y")].join();\ndeclare const fetch: unknown;',
     'real(attempt(() => { globalThis.fetch = async (u: string) => "mocked " + u; return "mocked it"; })); real(await user.all());')
case("global-timers", 'declare function setTimeout(f: () => void, ms: number): unknown; declare function setInterval(f: () => void, ms: number): unknown; declare function queueMicrotask(f: () => void): void; declare function setImmediate(f: () => void): unknown;\nexport const all = (): void => { setTimeout(() => console.log("a real timeout"), 0); globalThis.setTimeout(() => console.log("a real timeout by globalThis"), 0); setImmediate(() => console.log("a real immediate")); queueMicrotask(() => console.log("a real microtask")); };',
     'const seen: string[] = []; const olds = [globalThis.setTimeout, globalThis.setImmediate, globalThis.queueMicrotask]; real(attempt(() => { globalThis.setTimeout = () => { seen.push("fake timeout"); return 0; }; globalThis.setImmediate = () => { seen.push("fake immediate"); }; globalThis.queueMicrotask = () => { seen.push("fake microtask"); }; return "faked them"; })); user.all(); [globalThis.setTimeout, globalThis.setImmediate, globalThis.queueMicrotask] = olds; real(JSON.stringify(seen));')
case("global-date", 'export const all = (): string => [new Date().getFullYear(), Date.now(), typeof Date, new globalThis.Date().getFullYear(), new Date(0).toISOString(), Date.name].join();',
     'const Real = Date; real(attempt(() => { globalThis.Date = class FakeDate extends Real { constructor(...a: any[]) { if (a.length) super(...(a as [number])); else super(981173106000); } static now() { return 981173106000; } }; return "replaced it"; })); real(user.all()); globalThis.Date = Real; real(user.all().split(",")[0] !== "2001");')
case("date-now", 'export const all = (): string => [Date.now() === 5, new Date().getTime() === 5].join();', 'real(attempt(() => { Date.now = () => 5; return "patched it"; })); real(user.all());')
case("math-random", 'export const all = (): string => [Math.random() === 0.5, globalThis.Math.random() === 0.5].join();', 'real(attempt(() => { Math.random = () => 0.5; return "patched it"; })); real(user.all());')
case("global-math", 'export const all = (): string => [Math.max(1, 2), typeof Math.extra].join();\ndeclare global { interface Math { extra?: number } }', 'real(attempt(() => { globalThis.Math = Object.assign(Object.create(Math), { max: () => "fake max", extra: 1 }); return "replaced it"; })); real(user.all());')
case("global-promise", 'export const all = async (): Promise<string> => { const p = Promise.resolve(1); const q = (async () => 2)(); return [p.constructor.name, q.constructor.name, p instanceof Promise, q instanceof Promise, await p, await q, (Promise as any).mark ?? "no mark"].join(); };',
     'const Real = Promise; real(attempt(() => { globalThis.Promise = class Other<T> extends Real<T> { static mark = "other"; }; return "replaced it"; })); real(await user.all()); globalThis.Promise = Real;')
case("json-parse", 'export const all = (): string => JSON.stringify(JSON.parse("[1]"));', 'real(attempt(() => { const old = JSON.parse; JSON.parse = (t: string) => ["patched", old(t)]; return "patched it"; })); real(user.all());')
case("a-polyfill-that-is-guarded", 'export const all = (): string => [[1, 2].includes(2), "ab".padStart(3, "x"), Object.entries({ a: 1 }).length].join();', 'real(attempt(() => { if (!Array.prototype.includes) (Array.prototype as any).includes = () => "polyfilled"; if (!String.prototype.padStart) (String.prototype as any).padStart = () => "polyfilled"; if (typeof Object.entries !== "function") (Object as any).entries = () => []; return "nothing to fill"; })); real(user.all());')
case("a-polyfill-that-is-not-guarded", 'export const all = (): string => String(([1, 2] as any).last?.());', 'real(attempt(() => { (Array.prototype as any).last = function () { return this[this.length - 1]; }; return "added it"; })); real(user.all());')
case("error-limits-and-hooks", 'export const all = (): string => { const e = new Error("x"); return [typeof e.stack, (Error as any).stackTraceLimit, String(e.stack).split("\\n").length <= 3].join(); };\nexport function deep(n: number): string { return n ? deep(n - 1) : all(); }', 'real(attempt(() => { (Error as any).stackTraceLimit = 2; return "set it"; })); real(user.deep(6)); real(attempt(() => { (Error as any).captureStackTrace({}); return "captured"; }));')
case("process-members", 'export const all = (): string => [process.cwd(), process.platform, process.env.PATCHED, process.argv.length, typeof process.exit, process.hrtime.mark ?? "no mark", process.version.length > 0].join();',
     'real(attempt(() => { process.cwd = () => "/patched"; return "cwd"; }), attempt(() => { Object.defineProperty(process, "platform", { value: "patched-os" }); return "platform"; }), attempt(() => { process.env.PATCHED = "yes"; return "env"; }), attempt(() => { process.argv = ["a"]; return "argv"; }), attempt(() => { process.hrtime = Object.assign(() => [0, 0], { mark: "marked" }); return "hrtime"; })); real(user.all());')
case("process-exit", 'export const all = (): void => { process.exit(3); console.log("behind exit"); };', 'const seen: unknown[] = []; const old = process.exit; process.exit = (c: number) => { seen.push(c); }; user.all(); process.exit = old; real(JSON.stringify(seen));')
case("performance-and-crypto", 'export const all = (): string => [performance.now(), crypto.randomUUID(), globalThis.performance.now(), typeof crypto.getRandomValues].join();', 'real(attempt(() => { performance.now = () => 7; return "now"; }), attempt(() => { crypto.randomUUID = () => "fixed-uuid"; return "uuid"; })); real(user.all());')
case("members-of-bun", 'export const all = async (): Promise<string> => [typeof Bun.file, Bun.version.length > 0, await Bun.sleep(0), Bun.env.PATCHED, Bun.nanoseconds() === 9].join();', 'real(attempt(() => { Bun.sleep = async () => "no sleep"; return "sleep"; }), attempt(() => { Bun.env.PATCHED = "yes"; return "env"; }), attempt(() => { Bun.nanoseconds = () => 9; return "nanoseconds"; })); real(await user.all());')
case("global-constructors-of-the-host", 'declare const URL: any, TextEncoder: any, AbortController: any, Headers: any;\nexport const all = (): string => [new URL("http://a/b").mark ?? "real", new TextEncoder().mark ?? "real", new globalThis.URL("http://a/b").mark ?? "real", typeof AbortController, new Headers().mark ?? "real"].join();', 'real(attempt(() => { globalThis.URL = class { mark = "fake url"; }; globalThis.TextEncoder = class { mark = "fake encoder"; }; globalThis.Headers = class { mark = "fake headers"; }; return "replaced them"; })); real(user.all());')
case("a-global-of-the-programs-own", 'declare const __DEV__: boolean; declare let counter: number;\nexport const all = (): string => [typeof __DEV__ === "undefined" ? "not there" : __DEV__, globalThis.__DEV__, typeof counter === "undefined" ? "not there" : counter].join();\nexport const bump = (): void => { counter++; };', 'real(user.all()); globalThis.__DEV__ = true; globalThis.counter = 1; real(user.all()); user.bump(); real(user.all(), globalThis.counter); delete globalThis.__DEV__; real(user.all()); Object.defineProperty(globalThis, "__DEV__", { get: () => "by a getter", configurable: true }); real(user.all());')
case("a-global-function-is-deleted", 'declare function structuredClone<T>(v: T): T; declare const atob: unknown;\nexport const all = (): string => [typeof structuredClone, typeof atob, typeof globalThis.structuredClone].join();\nexport const call = (): unknown => structuredClone({ a: 1 });', 'real(user.all()); real(attempt(() => { delete globalThis.structuredClone; delete globalThis.atob; return "deleted them"; })); real(user.all()); real(JSON.stringify(attempt(() => user.call())));')
case("undefined-nan-infinity-and-globalthis", 'export const all = (): string => [undefined, NaN, Infinity, typeof globalThis].join();', 'real(attempt(() => { "use strict"; (globalThis as any).undefined = 1; return "stored"; }), attempt(() => { (globalThis as any).NaN = 1; return "stored"; }), attempt(() => Reflect.set(globalThis, "Infinity", 1)), attempt(() => Reflect.defineProperty(globalThis, "undefined", { value: 2 }))); real(user.all());')
case("intl-members", 'export const all = (): string => [typeof Intl.DateTimeFormat, new Intl.NumberFormat("en").format(1.5), (Intl as any).extra ?? "no extra"].join();', 'real(attempt(() => { (Intl as any).extra = "added"; return "added it"; }), attempt(() => { (Intl as any).NumberFormat = class { format() { return "fake format"; } }; return "replaced it"; })); real(user.all());')
case("reflect-and-object-statics", 'export const all = (): string => [Object.keys({ a: 1 }).join(), Reflect.ownKeys({ b: 1 }).join(), Array.isArray([]), Number.isInteger(1)].join("|");', 'real(attempt(() => { Object.keys = () => ["patched"]; return "keys"; }), attempt(() => { Reflect.ownKeys = () => ["patched"]; return "ownKeys"; }), attempt(() => { Array.isArray = (() => "patched") as any; return "isArray"; }), attempt(() => { Number.isInteger = (() => "patched") as any; return "isInteger"; })); real(user.all());')
case("a-symbol-keyed-global", 'const KEY = Symbol.for("my.registry");\nexport const all = (): string => JSON.stringify(globalThis[KEY] ?? null);\nexport const add = (v: string): void => { (globalThis[KEY] ??= []).push(v); };', 'real(user.all()); user.add("one"); globalThis[Symbol.for("my.registry")].push("two"); real(user.all());')
for name, files in cases.items():
    os.makedirs(f"{out}/{name}", exist_ok=True)
    for f, text in files.items(): open(f"{out}/{name}/{f}", "w").write(text)
print(len(cases), "cases")
